-- Get all columns from all rows
SELECT * FROM users;

-- Get specific columns
SELECT name, city FROM users;

-- Rename columns with aliases
SELECT name AS full_name, email AS contact FROM users;

-- Calculated columns
SELECT name, price, stock, price * stock AS inventory_value
FROM products;

-- Unique values only
SELECT DISTINCT city FROM users;

-- Limit number of rows
SELECT * FROM products LIMIT 3;

-- Expressions without a table
SELECT 2 + 2 AS sum, 'SQL' AS language, UPPER('hello') AS greeting;
